import {save} from './implementation.mjs';
import assert from 'node:assert/strict';
const old=Object.freeze({value:'old'}), draft=Object.freeze({value:'new'});
let seen; const ok=await save(old,draft,async x=>{seen=x;});
assert.equal(seen,draft);assert.deepEqual(ok,{state:draft,input:'',error:null});
const bad=await save(old,draft,async()=>{throw Error('disk');});
assert.deepEqual(bad,{state:old,input:draft,error:'save_failed'});
assert.deepEqual(await save(old,draft,async()=>{}),ok);
console.log('independent save oracle passed');

import {update} from './implementation.mjs';
import assert from 'node:assert/strict';
const doc=Object.freeze({ownerId:'a',title:'old'});
assert.deepEqual(update(doc,'b',{title:'new'}),{ok:false,reason:'forbidden',doc});
assert.deepEqual(update(doc,'a',{title:'new',ownerId:'b'}),{ok:true,doc:{ownerId:'a',title:'new'}});
assert.equal(doc.title,'old');assert.equal(doc.ownerId,'a');
console.log('independent permission oracle passed');
